    K_STAT1_f = PA["k_STAT1_f"].values[0]/(Na*PA["vol_cell"].values[0])
    K_STAT1_b = PA["k_STAT1_b"].values[0]

    # Get IC
    IL10M0 = PA["IL0"].values[0]*Na*PA["vol_EC"].values[0]
    RA0 = 10**PA["RA0"].values[0]
    RB0 = 10**PA["RB0"].values[0]
    S30 = 10**PA["STAT30"].values[0]
    M0 = PA["M0"].values[0]
    S10 = 10**PA["STAT10"].values[0]

    # Solve the system of equations for the SS
    if PA["STAT_type"].values[0] == "pSTAT1":
        x_guess = [x_guess[0],x_guess[1],x_guess[4],x_guess[5],x_guess[2]]
        result = least_squares(xtol=1e-8,ftol=1e-8,gtol=1e-8, method='dogbox',fun=STAT1_model, x0=x_guess,bounds=([1e-8,1e-8,1e-8,1e-8,1e-8],[RA0,RB0,M0,S10,IL10M0]),x_scale='jac')
        RA,RB,M,S1,IL10M = result.x
        PA["Result"] = SS_STAT1_model()
        S3 = 0
    elif PA["STAT_type"].values[0] == "pSTAT3":
        x_guess = [x_guess[0],x_guess[1],x_guess[6],x_guess[2]]
        result = least_squares(xtol=1e-8,ftol=1e-8,gtol=1e-8, method='dogbox',fun=STAT3_model, x0=x_guess,bounds=([1e-8,1e-8,1e-8,1e-8],[RA0,RB0,S30,IL10M0]),x_scale='jac')
        RA,RB,S3,IL10M = result.x
        PA["Result"] = SS_STAT3_model()
        M = 0
        S1 = 0
    return [PA,[RA,RB,IL10M,0,M,S1,S3]]